-- FERRAMENTAS (protegido)
local _k={38,246,218,4,10,142,130,49,215,145,172,70,175,82,22,209}
local _h=[==[]==]
local _t={}
for _j=1,#_k do
  local _m,_kb={}, _k[_j]
  for _b=0,255 do
    local _r,_p,_a,_c=0,1,_b,_kb
    for _=1,8 do
      local _u,_v=_a%2,_c%2
      if _u~=_v then _r=_r+_p end
      _a=math.floor(_a/2); _c=math.floor(_c/2); _p=_p*2
    end
    _m[_b]=string.char(_r)
  end
  _t[_j]=_m
end
local _i,_n=0,#_k
local _c=_h:gsub("%x%x",function(_x)
  _i=_i+1
  return _t[((_i-1)%_n)+1][tonumber(_x,16)]
end)
local _f=loadstring and loadstring(_c) or (load and load(_c))
if _f then _f() end
